@dataclass(frozen=True)
class SEOMigrationGenerationBudget:
    context_budget_chars: int = _MIGRATION_CONTEXT_BUDGET_DEFAULT_CHARS
    recommendation_limit: int = _MIGRATION_RECOMMENDATION_LIMIT_DEFAULT
    competitor_limit: int = _MIGRATION_COMPETITOR_LIMIT_DEFAULT
    source_page_summary_limit: int = _MIGRATION_SOURCE_PAGE_SUMMARY_LIMIT_DEFAULT
    media_asset_limit: int = _MIGRATION_MEDIA_ASSET_LIMIT_DEFAULT
    generated_page_limit: int = _MIGRATION_GENERATED_PAGE_LIMIT_DEFAULT
    generated_file_limit: int = _MIGRATION_GENERATED_FILE_LIMIT_DEFAULT
    generation_depth: str = "standard"
    variation_level: str = "balanced"
    require_page_variety: bool = True
    require_design_variation: bool = True

    def to_context_payload(self) -> dict[str, object]:
        return {
            "migration_context_budget_chars": max(
                _MIGRATION_CONTEXT_BUDGET_MIN_CHARS,
                min(_MIGRATION_CONTEXT_BUDGET_MAX_CHARS, int(self.context_budget_chars)),
            ),
            "migration_recommendation_limit": max(
                _MIGRATION_RECOMMENDATION_LIMIT_MIN,
                min(_MIGRATION_RECOMMENDATION_LIMIT_MAX, int(self.recommendation_limit)),
            ),
            "migration_competitor_limit": max(
                _MIGRATION_COMPETITOR_LIMIT_MIN,
                min(_MIGRATION_COMPETITOR_LIMIT_MAX, int(self.competitor_limit)),
            ),
            "migration_source_page_summary_limit": max(
                _MIGRATION_SOURCE_PAGE_SUMMARY_LIMIT_MIN,
                min(_MIGRATION_SOURCE_PAGE_SUMMARY_LIMIT_MAX, int(self.source_page_summary_limit)),
            ),
            "migration_media_asset_limit": max(
                _MIGRATION_MEDIA_ASSET_LIMIT_MIN,
                min(_MIGRATION_MEDIA_ASSET_LIMIT_MAX, int(self.media_asset_limit)),
            ),
            "migration_generated_page_limit": max(
                _MIGRATION_GENERATED_PAGE_LIMIT_MIN,
                min(_MIGRATION_GENERATED_PAGE_LIMIT_MAX, int(self.generated_page_limit)),
            ),
            "migration_generated_file_limit": max(
                _MIGRATION_GENERATED_FILE_LIMIT_MIN,
                min(_MIGRATION_GENERATED_FILE_LIMIT_MAX, int(self.generated_file_limit)),
            ),
            "migration_generation_depth": self.generation_depth,
            "migration_variation_level": self.variation_level,
            "migration_require_page_variety": bool(self.require_page_variety),
            "migration_require_design_variation": bool(self.require_design_variation),
        }


@dataclass(frozen=True)
class SEOMigrationGenerationSafety:
    provider_timeout_seconds: int = 300
    preflight_mode: str = "compact_fallback"
    max_final_input_chars: int = _MIGRATION_MAX_FINAL_INPUT_DEFAULT_CHARS
    max_difficulty_score: int = _MIGRATION_MAX_DIFFICULTY_DEFAULT_SCORE
    compact_fallback_enabled: bool = True
    compact_page_limit: int = _MIGRATION_COMPACT_PAGE_LIMIT_DEFAULT
    compact_media_asset_limit: int = _MIGRATION_COMPACT_MEDIA_LIMIT_DEFAULT
    compact_recommendation_limit: int = _MIGRATION_COMPACT_RECOMMENDATION_LIMIT_DEFAULT

    def to_context_payload(self) -> dict[str, object]:
        preflight_mode = str(self.preflight_mode or "").strip().lower()
        if preflight_mode not in {"compact_fallback", "block_before_provider"}:
            preflight_mode = "compact_fallback"
        return {
            "migration_provider_timeout_seconds": max(
                _MIGRATION_DRAFT_TIMEOUT_MIN_SECONDS,
                min(_MIGRATION_DRAFT_TIMEOUT_MAX_SECONDS, int(self.provider_timeout_seconds)),
            ),
            "migration_preflight_mode": preflight_mode,
            "migration_max_final_input_chars": max(
                _MIGRATION_MAX_FINAL_INPUT_MIN_CHARS,
                min(_MIGRATION_MAX_FINAL_INPUT_MAX_CHARS, int(self.max_final_input_chars)),
            ),
            "migration_max_difficulty_score": max(
                _MIGRATION_MAX_DIFFICULTY_MIN_SCORE,
                min(_MIGRATION_MAX_DIFFICULTY_MAX_SCORE, int(self.max_difficulty_score)),
            ),
            "migration_compact_fallback_enabled": bool(self.compact_fallback_enabled),
            "migration_compact_page_limit": max(
                _MIGRATION_COMPACT_PAGE_LIMIT_MIN,
                min(_MIGRATION_COMPACT_PAGE_LIMIT_MAX, int(self.compact_page_limit)),
            ),
            "migration_compact_media_asset_limit": max(
                _MIGRATION_COMPACT_MEDIA_LIMIT_MIN,
                min(_MIGRATION_COMPACT_MEDIA_LIMIT_MAX, int(self.compact_media_asset_limit)),
            ),
            "migration_compact_recommendation_limit": max(
                _MIGRATION_COMPACT_RECOMMENDATION_LIMIT_MIN,
                min(_MIGRATION_COMPACT_RECOMMENDATION_LIMIT_MAX, int(self.compact_recommendation_limit)),
            ),
        }


class _SEOMediaImportNoRedirectHandler(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):  # noqa: ANN001
        del req, fp, code, msg, headers, newurl
        return None


class SEOMigrationService:
    def __init__(
        self,
        *,
        session: Session,
        business_repository: BusinessRepository,
        seo_site_repository: SEOSiteRepository,
        seo_migration_repository: SEOMigrationRepository,
        seo_audit_repository: SEOAuditRepository,
        seo_audit_summary_repository: SEOAuditSummaryRepository,
        seo_recommendation_repository: SEORecommendationRepository,
        seo_recommendation_narrative_repository: SEORecommendationNarrativeRepository,
        seo_competitor_repository: SEOCompetitorRepository,
        seo_competitor_summary_repository: SEOCompetitorSummaryRepository,
        ingest_service: SEOMigrationSourceIngestService,
        context_assembler: SEOMigrationContextAssembler,
        artifact_provider: SEOMigrationArtifactGenerationProvider,
        github_publisher: SEOMigrationGitHubPublisher | None = None,
        github_publish_config_service: GitHubPublishConfigService | None = None,
        provider_name: str,
        provider_model_name: str,
        env_default_model_name: str | None = None,
        prompt_version: str = SEO_MIGRATION_PROMPT_VERSION,
        prompt_text_recommendations: str = "",
        publish_commit_message_prefix: str = "[MBSRN Migration]",
        deploy_default_workflow_id: str = "deploy-www-prod.yml",
        deploy_default_ref: str = "main",
        deploy_secret_gcp_key: str | None = None,
        deploy_secret_git_userid: str | None = None,
        deploy_secret_git_email: str | None = None,
        deploy_secret_git_token: str | None = None,
        managed_site_private_image_auth_enabled: bool = True,
        remote_image_import_enabled: bool = True,
    ) -> None:
        self.session = session
        self.business_repository = business_repository
        self.seo_site_repository = seo_site_repository
        self.seo_migration_repository = seo_migration_repository
        self.seo_audit_repository = seo_audit_repository
        self.seo_audit_summary_repository = seo_audit_summary_repository
        self.seo_recommendation_repository = seo_recommendation_repository
        self.seo_recommendation_narrative_repository = seo_recommendation_narrative_repository
        self.seo_competitor_repository = seo_competitor_repository
        self.seo_competitor_summary_repository = seo_competitor_summary_repository
        self.ingest_service = ingest_service
        self.context_assembler = context_assembler
        self.artifact_provider = artifact_provider
        self.draft_provider_configured = not isinstance(
            artifact_provider,
            MisconfiguredSEOMigrationArtifactGenerationProvider,
        )
        if github_publisher is None:
            github_publisher = MisconfiguredSEOMigrationGitHubPublisher(
                safe_message="GitHub publishing integration is unavailable in this runtime.",
                reason_code=_GITHUB_PUBLISHER_REASON_RUNTIME_INTEGRATION_UNAVAILABLE,
            )
        self.github_publisher = github_publisher
        self.github_publisher_configured = not isinstance(
            github_publisher,
            MisconfiguredSEOMigrationGitHubPublisher,
        )
        self.github_publisher_reason_code = ""
        self.github_publisher_status_message = ""
        self.github_publisher_safe_message = ""
        if isinstance(github_publisher, MisconfiguredSEOMigrationGitHubPublisher):
            normalized_reason_code = _normalize_string(
                getattr(github_publisher, "reason_code", None),
                max_length=80,
            )
            self.github_publisher_reason_code = normalized_reason_code or "publisher_not_configured"
            self.github_publisher_safe_message = (
                _normalize_string(getattr(github_publisher, "safe_message", None), max_length=240)
                or "GitHub publishing integration is unavailable in this runtime."
            )
            self.github_publisher_status_message = self._runtime_publisher_reason_message(
                reason_code=self.github_publisher_reason_code,
                action="publish",
            )
        self.github_publish_config_service = github_publish_config_service
        self.provider_name = provider_name
        self.provider_model_name = provider_model_name
        self._configured_provider_model_name = _normalize_string(provider_model_name, max_length=128)
        self._env_default_model_name = _normalize_string(env_default_model_name, max_length=128)
        self.prompt_version = prompt_version
        self.prompt_text_recommendations = prompt_text_recommendations
        self.publish_commit_message_prefix = publish_commit_message_prefix.strip() or "[MBSRN Migration]"
        self.deploy_default_workflow_id = deploy_default_workflow_id.strip() or "deploy-www-prod.yml"
        self.deploy_default_ref = deploy_default_ref.strip() or "main"
        self.deploy_secret_gcp_key = (deploy_secret_gcp_key or "").strip() or None
        self.deploy_secret_git_userid = (deploy_secret_git_userid or "").strip() or None
        self.deploy_secret_git_email = (deploy_secret_git_email or "").strip() or None
        self.deploy_secret_git_token = (deploy_secret_git_token or "").strip() or None
        self.managed_site_private_image_auth_enabled = bool(managed_site_private_image_auth_enabled)
        self.remote_image_import_enabled = bool(remote_image_import_enabled)
        self.runtime_build_metadata = get_runtime_build_metadata()
        self._resolved_migration_draft_timeout_seconds = _MIGRATION_DRAFT_TIMEOUT_DEFAULT_SECONDS
        self._resolved_migration_draft_timeout_source = "default"
        self._resolved_migration_generation_safety = SEOMigrationGenerationSafety()
        self._resolved_migration_generation_safety_source = "default"
        self.media_storage_root = _resolve_migration_media_storage_root()

    def create_or_update_workspace(
        self,
        *,
        business_id: str,
        site_id: str,
        source_url: str | None = None,
        operator_requirements: dict[str, object] | None = None,
        enriched_content_notes: dict[str, object] | None = None,
        publish_config: dict[str, object] | None = None,
        deploy_config: dict[str, object] | None = None,
        deploy_config_field_names: set[str] | None = None,
        analytics_config: dict[str, object] | None = None,
        principal_id: str | None,
        principal_role: PrincipalRole | str | None = None,
    ) -> SEOMigrationWorkspace:
        site = self._require_site(business_id=business_id, site_id=site_id)
        workspace = self.seo_migration_repository.get_workspace_for_business_site(business_id, site_id)
        normalized_deploy_config = (
            self._sanitize_workspace_deploy_config_update(
                current_config=workspace.deploy_config_json if workspace is not None else None,
                incoming_config=deploy_config,
                principal_role=principal_role,
                deploy_config_field_names=deploy_config_field_names,
            )
            if deploy_config is not None
            else _normalize_deploy_config(None)
        )
        if workspace is None:
            workspace = SEOMigrationWorkspace(
                id=str(uuid4()),
                business_id=business_id,
                site_id=site_id,
                source_url=source_url,
                source_site_status="not_ingested",
                migration_status="draft",
                operator_requirements_json=_normalize_json_dict(operator_requirements),
                enriched_content_notes_json=_normalize_json_dict(enriched_content_notes),
                brand_business_facts_snapshot_json=self._build_brand_business_snapshot(site),
                imported_source_snapshot_json={},
                publish_config_json=_normalize_workspace_publish_config(publish_config),
                deploy_config_json=normalized_deploy_config,
                analytics_config_json=_normalize_analytics_config(analytics_config),
                publish_status="not_ready",
                deploy_status="not_ready",
                publish_history_json=[],
                deploy_history_json=[],
                created_by_principal_id=principal_id,
                updated_by_principal_id=principal_id,
            )
            self._update_workspace_readiness_statuses(workspace=workspace, site=site)
            self.seo_migration_repository.create_workspace(workspace)
        else:
            if source_url is not None:
                workspace.source_url = source_url
            if operator_requirements is not None:
                workspace.operator_requirements_json = _normalize_json_dict(operator_requirements)
            if enriched_content_notes is not None:
                workspace.enriched_content_notes_json = _normalize_json_dict(enriched_content_notes)
            if publish_config is not None:
                workspace.publish_config_json = _normalize_workspace_publish_config(publish_config)
            if deploy_config is not None:
                workspace.deploy_config_json = normalized_deploy_config
            if analytics_config is not None:
                workspace.analytics_config_json = _normalize_analytics_config(analytics_config)
            workspace.brand_business_facts_snapshot_json = self._build_brand_business_snapshot(site)
            self._update_workspace_readiness_statuses(workspace=workspace, site=site)
            workspace.updated_by_principal_id = principal_id
            self.seo_migration_repository.save_workspace(workspace)
        self._commit_with_constraint_handling()
        self.session.refresh(workspace)
        return workspace

    def get_workspace(self, *, business_id: str, site_id: str) -> SEOMigrationWorkspace:
        self._require_site(business_id=business_id, site_id=site_id)
        workspace = self.seo_migration_repository.get_workspace_for_business_site(business_id, site_id)
        if workspace is None:
            raise SEOMigrationNotFoundError("Migration workspace not found")
        return workspace

    @staticmethod
    def _build_workspace_media_preview_url(
        *,
        business_id: str,
        site_id: str,
        media_asset: dict[str, object],
    ) -> str | None:
        if _normalize_media_workspace_status(media_asset.get("workspace_status")) != _MIGRATION_MEDIA_WORKSPACE_STATUS_ACTIVE:
            return None
        asset_id = _normalize_string(media_asset.get("asset_id"), max_length=80)
        if asset_id is None:
            return None
        encoded_asset_id = quote(asset_id, safe="")
        return f"/api/businesses/{business_id}/seo/sites/{site_id}/migration/media/assets/{encoded_asset_id}/preview"

    def _to_media_asset_read_payload(
        self,
        *,
        business_id: str,
        site_id: str,
        media_asset: dict[str, object],
    ) -> dict[str, object]:
        return _sanitize_media_asset_for_read(
            media_asset,
            preview_url=self._build_workspace_media_preview_url(
                business_id=business_id,
                site_id=site_id,
                media_asset=media_asset,
            ),
        )

    def list_workspace_media_assets(
        self,
        *,
        business_id: str,
        site_id: str,
    ) -> dict[str, object]:
        workspace = self.get_workspace(business_id=business_id, site_id=site_id)
        return self._collect_workspace_media_assets(
            workspace=workspace,
            business_id=business_id,
            site_id=site_id,
        )

    def upload_workspace_media_asset(
        self,
        *,
        business_id: str,
        site_id: str,
        filename: str,
        content_type: str | None,
        payload: bytes,
        selected_for_draft: bool,
        category: str | None,
        alt_text: str | None,
        description: str | None,
        usage_note: str | None,
        page_assignment: str | None,
        principal_id: str | None,
    ) -> dict[str, object]:
        workspace = self.get_workspace(business_id=business_id, site_id=site_id)
        self._require_site(business_id=business_id, site_id=site_id)
        current_uploads = _normalize_workspace_operator_media_assets(workspace.enriched_content_notes_json)
        if len(current_uploads) >= _MIGRATION_MEDIA_UPLOAD_MAX_COUNT:
            raise SEOMigrationValidationError(
                "Media upload limit reached for this workspace.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code="workspace_media_upload_limit_reached",
                workspace_id=workspace.id,
            )
        normalized_filename = _normalize_media_filename(filename)
        if normalized_filename is None:
            raise SEOMigrationValidationError(
                "Upload filename is required.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code="media_upload_filename_required",
                workspace_id=workspace.id,
            )
        normalized_declared_content_type = _normalize_media_content_type(content_type)
        if normalized_declared_content_type is None:
            raise SEOMigrationValidationError(
                "Unsupported media content type.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code=_MIGRATION_MEDIA_DIAGNOSTIC_REASON_UNSUPPORTED_MIME,
                workspace_id=workspace.id,
            )
        if not payload:
            raise SEOMigrationValidationError(
                "Upload payload is empty.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code="media_upload_empty",
                workspace_id=workspace.id,
            )
        if len(payload) > _MIGRATION_MEDIA_UPLOAD_MAX_BYTES:
            raise SEOMigrationValidationError(
                "Uploaded media exceeds maximum size.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code=_MIGRATION_MEDIA_DIAGNOSTIC_REASON_FILE_TOO_LARGE,
                workspace_id=workspace.id,
            )
        sniffed_content_type = _detect_media_content_type(payload)
        if sniffed_content_type not in _MIGRATION_MEDIA_UPLOAD_ALLOWED_CONTENT_TYPES:
            raise SEOMigrationValidationError(
                "Uploaded media type is not supported.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code=_MIGRATION_MEDIA_DIAGNOSTIC_REASON_UNSUPPORTED_MIME,
                workspace_id=workspace.id,
            )
        if sniffed_content_type != normalized_declared_content_type:
            raise SEOMigrationValidationError(
                "Uploaded media content type does not match the file payload.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code="media_upload_content_type_mismatch",
                workspace_id=workspace.id,
            )
        ext = _MIGRATION_MEDIA_UPLOAD_ALLOWED_CONTENT_TYPES.get(sniffed_content_type, "")
        provided_extension = _extract_file_extension(normalized_filename)
        if provided_extension and provided_extension not in _MIGRATION_MEDIA_UPLOAD_ALLOWED_EXTENSIONS:
            raise SEOMigrationValidationError(
                "Unsupported media file extension.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code="media_upload_extension_not_allowed",
                workspace_id=workspace.id,
            )
        asset_id = f"upl-{uuid4()}"
        storage_key = _build_workspace_media_storage_key(
            business_id=business_id,
            site_id=site_id,
            asset_id=asset_id,
            extension=ext,
        )
        _write_workspace_media_file(
            storage_root=self.media_storage_root,
            storage_key=storage_key,
            payload=payload,
        )
        width, height = _detect_image_dimensions(payload, sniffed_content_type)
        media_asset: dict[str, object] = {
            "asset_id": asset_id,
            "display_filename": normalized_filename,
            "content_type": sniffed_content_type,
            "size_bytes": max(0, int(len(payload))),
            "width": width,
            "height": height,
            "provenance": "operator_upload",
            "selected_for_draft": bool(selected_for_draft),
            "import_status": "selected" if bool(selected_for_draft) else "uploaded",
            "category": _normalize_media_category(category),
            "alt_text": _normalize_string(alt_text, max_length=240),
            "description": _normalize_string(description, max_length=800),
            "usage_note": _normalize_string(usage_note, max_length=400),
            "page_assignment": _normalize_string(page_assignment, max_length=120),
            "storage_key": storage_key,
            "created_at": utc_now().isoformat(),
        }
        current_uploads.append(media_asset)
        trimmed_uploads = current_uploads[-_MIGRATION_MEDIA_UPLOAD_MAX_COUNT:]
        enriched = _normalize_json_dict(workspace.enriched_content_notes_json)
        enriched["workspace_media_assets"] = trimmed_uploads
        workspace.enriched_content_notes_json = enriched
        workspace.updated_by_principal_id = principal_id
        self.seo_migration_repository.save_workspace(workspace)
        self.session.commit()
        self.session.refresh(workspace)
        return self._to_media_asset_read_payload(
            business_id=business_id,
            site_id=site_id,
            media_asset=media_asset,
        )

    def update_workspace_media_asset(
        self,
        *,
        business_id: str,
        site_id: str,
        asset_id: str,
        selected_for_draft: bool | None,
        apply_suggested_metadata: bool = False,
        category: str | None = None,
        alt_text: str | None = None,
        description: str | None = None,
        usage_note: str | None = None,
        page_assignment: str | None = None,
        principal_id: str | None = None,
    ) -> dict[str, object]:
        workspace = self.get_workspace(business_id=business_id, site_id=site_id)
        self._require_site(business_id=business_id, site_id=site_id)
        target_asset_id = _normalize_string(asset_id, max_length=80)
        if target_asset_id is None:
            raise SEOMigrationValidationError(
                "media asset id is required.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code="media_asset_id_required",
                workspace_id=workspace.id,
            )
        source_snapshot = _normalize_json_dict(workspace.imported_source_snapshot_json)
        discovered_assets = _normalize_workspace_discovered_media_assets(source_snapshot.get("discovered_images"))
        operator_assets = _normalize_workspace_operator_media_assets(workspace.enriched_content_notes_json)
        updated_asset: dict[str, object] | None = None

        for collection in (discovered_assets, operator_assets):
            for item in collection:
                if _normalize_string(item.get("asset_id"), max_length=80) != target_asset_id:
                    continue
                if not _is_workspace_media_asset_visible(item):
                    raise SEOMigrationValidationError(
                        "This media asset is no longer available in the active workspace list.",
                        failure_category="artifact_invalid",
                        failure_reason="validation_failed",
                        error_code=_MIGRATION_MEDIA_REASON_ALREADY_REMOVED,
                        workspace_id=workspace.id,
                    )
                if isinstance(selected_for_draft, bool):
                    if selected_for_draft:
                        state_reason = _media_asset_unusable_reason_code(item)
                        if state_reason is not None:
                            raise SEOMigrationValidationError(
                                _media_action_block_message(reason_code=state_reason),
                                failure_category="artifact_invalid",
                                failure_reason="validation_failed",
                                error_code=state_reason or _MIGRATION_MEDIA_REASON_ACTION_NOT_ALLOWED_FOR_STATE,
                                workspace_id=workspace.id,
                            )
                    item["selected_for_draft"] = bool(selected_for_draft)
                    current_status = _normalize_string(item.get("import_status"), max_length=40)
                    provenance = _normalize_string(item.get("provenance"), max_length=40) or "source_site_import"
                    has_storage_key = _normalize_string(item.get("storage_key"), max_length=240) is not None
                    if selected_for_draft:
                        if provenance == "operator_upload":
                            item["import_status"] = "selected"
                        elif has_storage_key or current_status in {"selected", "imported", "available"}:
                            item["import_status"] = "selected"
                        else:
                            item["import_status"] = "discovered"
                    elif current_status == "selected":
                        if provenance == "operator_upload":
                            item["import_status"] = "uploaded"
                        else:
                            item["import_status"] = "imported" if has_storage_key else "discovered"
                if apply_suggested_metadata:
                    suggestion = _normalize_media_metadata_suggestion(item.get("metadata_suggestion"))
                    if suggestion.get("suggestion_status") != _MIGRATION_MEDIA_SUGGESTION_STATUS_COMPLETED:
                        raise SEOMigrationValidationError(
                            "No completed metadata suggestion is available for this asset.",
                            failure_category="artifact_invalid",
                            failure_reason="validation_failed",
                            error_code=_MIGRATION_MEDIA_REASON_ANALYSIS_NOT_AVAILABLE,
                            workspace_id=workspace.id,
                        )
                    suggested_category = _normalize_media_category(suggestion.get("suggested_category"))
                    if suggested_category is not None:
                        item["category"] = suggested_category
                    suggested_alt_text = _normalize_string(suggestion.get("suggested_alt_text"), max_length=240)
                    if suggested_alt_text is not None:
                        item["alt_text"] = suggested_alt_text
                    suggested_description = _normalize_string(suggestion.get("suggested_description"), max_length=800)
                    if suggested_description is not None:
                        item["description"] = suggested_description
                    suggested_usage_note = _normalize_string(suggestion.get("suggested_usage_note"), max_length=400)
                    if suggested_usage_note is not None:
                        item["usage_note"] = suggested_usage_note
                    suggested_page_assignment = _normalize_string(
                        suggestion.get("suggested_page_assignment"),
                        max_length=120,
                    )
                    if suggested_page_assignment is not None:
                        item["page_assignment"] = suggested_page_assignment
                    item["metadata_suggestion_applied"] = True
                    item["metadata_suggestion_applied_at"] = utc_now().isoformat()
                if category is not None:
                    item["category"] = _normalize_media_category(category)
                if alt_text is not None:
                    item["alt_text"] = _normalize_string(alt_text, max_length=240)
                if description is not None:
                    item["description"] = _normalize_string(description, max_length=800)
                if usage_note is not None:
                    item["usage_note"] = _normalize_string(usage_note, max_length=400)
                if page_assignment is not None:
                    item["page_assignment"] = _normalize_string(page_assignment, max_length=120)
                updated_asset = item
                break
            if updated_asset is not None:
                break
        if updated_asset is None:
            raise SEOMigrationNotFoundError("Migration media asset not found")
        source_snapshot["discovered_images"] = discovered_assets
        workspace.imported_source_snapshot_json = source_snapshot
        enriched = _normalize_json_dict(workspace.enriched_content_notes_json)
        enriched["workspace_media_assets"] = operator_assets
        workspace.enriched_content_notes_json = enriched
        workspace.updated_by_principal_id = principal_id
        self.seo_migration_repository.save_workspace(workspace)
        self.session.commit()
        self.session.refresh(workspace)
        return self._to_media_asset_read_payload(
            business_id=business_id,
            site_id=site_id,
            media_asset=updated_asset,
        )

    def preview_workspace_media_asset(
        self,
        *,
        business_id: str,
        site_id: str,
        asset_id: str,
    ) -> tuple[str, bytes]:
        workspace = self.get_workspace(business_id=business_id, site_id=site_id)
        self._require_site(business_id=business_id, site_id=site_id)
        target_asset_id = _normalize_string(asset_id, max_length=80)
        if target_asset_id is None:
            raise SEOMigrationValidationError(
                "media asset id is required.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code="media_asset_id_required",
                workspace_id=workspace.id,
            )
        source_snapshot = _normalize_json_dict(workspace.imported_source_snapshot_json)
        discovered_assets = _normalize_workspace_discovered_media_assets(source_snapshot.get("discovered_images"))
        operator_assets = _normalize_workspace_operator_media_assets(workspace.enriched_content_notes_json)

        target_asset: dict[str, object] | None = None
        for collection in (discovered_assets, operator_assets):
            for item in collection:
                if _normalize_string(item.get("asset_id"), max_length=80) != target_asset_id:
                    continue
                target_asset = item
                break
            if target_asset is not None:
                break
        if target_asset is None:
            raise SEOMigrationNotFoundError("Migration media asset not found")
        if not _is_workspace_media_asset_visible(target_asset):
            raise SEOMigrationValidationError(
                "This media asset is not available for preview.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code=_MIGRATION_MEDIA_REASON_STORAGE_PREVIEW_NOT_AVAILABLE,
                workspace_id=workspace.id,
            )

        declared_content_type = _normalize_media_content_type(target_asset.get("content_type"))
        if declared_content_type is not None and declared_content_type not in _MIGRATION_MEDIA_UPLOAD_ALLOWED_CONTENT_TYPES:
            raise SEOMigrationValidationError(
                "Unsupported media content type.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code=_MIGRATION_MEDIA_REASON_UNSUPPORTED_CONTENT_TYPE,
                workspace_id=workspace.id,
            )

        payload, _preview_unavailable_reason = _read_workspace_media_payload_for_materialization(
            media_asset=target_asset,
            storage_root=self.media_storage_root,
            business_id=business_id,
            site_id=site_id,
        )
        if not payload:
            raise SEOMigrationValidationError(
                "Storage preview is unavailable for this media asset.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code=_MIGRATION_MEDIA_REASON_STORAGE_PREVIEW_NOT_AVAILABLE,
                workspace_id=workspace.id,
            )
        if len(payload) > _MIGRATION_MEDIA_UPLOAD_MAX_BYTES:
            raise SEOMigrationValidationError(
                "Stored media exceeds supported preview size.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code=_MIGRATION_MEDIA_REASON_FILE_TOO_LARGE,
                workspace_id=workspace.id,
            )
        detected_content_type = _detect_media_content_type(payload)
        if detected_content_type not in _MIGRATION_MEDIA_UPLOAD_ALLOWED_CONTENT_TYPES:
            raise SEOMigrationValidationError(
                "Unsupported media content type.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code=_MIGRATION_MEDIA_REASON_UNSUPPORTED_CONTENT_TYPE,
                workspace_id=workspace.id,
            )
        if declared_content_type is not None and declared_content_type != detected_content_type:
            raise SEOMigrationValidationError(
                "Unsupported media content type.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code=_MIGRATION_MEDIA_REASON_UNSUPPORTED_CONTENT_TYPE,
                workspace_id=workspace.id,
            )
        return detected_content_type, payload

    def update_workspace_media_asset_lifecycle(
        self,
        *,
        business_id: str,
        site_id: str,
        asset_id: str,
        action: str,
        principal_id: str | None,
    ) -> dict[str, object]:
        workspace = self.get_workspace(business_id=business_id, site_id=site_id)
        self._require_site(business_id=business_id, site_id=site_id)
        normalized_action = (_normalize_string(action, max_length=20) or "").lower()
        if normalized_action not in {"remove", "ignore"}:
            raise SEOMigrationValidationError(
                "Unsupported media lifecycle action.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code=_MIGRATION_MEDIA_REASON_ACTION_NOT_ALLOWED_FOR_STATE,
                workspace_id=workspace.id,
            )
        target_asset_id = _normalize_string(asset_id, max_length=80)
        if target_asset_id is None:
            raise SEOMigrationValidationError(
                "media asset id is required.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code="media_asset_id_required",
                workspace_id=workspace.id,
            )
        source_snapshot = _normalize_json_dict(workspace.imported_source_snapshot_json)
        discovered_assets = _normalize_workspace_discovered_media_assets(source_snapshot.get("discovered_images"))
        operator_assets = _normalize_workspace_operator_media_assets(workspace.enriched_content_notes_json)

        target_asset: dict[str, object] | None = None
        target_collection: list[dict[str, object]] | None = None
        for collection in (discovered_assets, operator_assets):
            for item in collection:
                if _normalize_string(item.get("asset_id"), max_length=80) != target_asset_id:
                    continue
                target_asset = item
                target_collection = collection
                break
            if target_asset is not None:
                break

        if target_asset is None or target_collection is None:
            return {
                "asset_id": target_asset_id,
                "status": _MIGRATION_MEDIA_REASON_NOT_FOUND,
                "reason_code": _MIGRATION_MEDIA_REASON_NOT_FOUND,
                "media_asset": None,
            }

        current_workspace_status = _normalize_media_workspace_status(target_asset.get("workspace_status"))
        provenance = _normalize_string(target_asset.get("provenance"), max_length=40) or "source_site_import"
        is_discovered = provenance == "source_site_import"
        is_imported = _is_discovered_media_asset_imported(target_asset)
        if normalized_action == "ignore":
            if not is_discovered or is_imported:
                return {
                    "asset_id": target_asset_id,
                    "status": _MIGRATION_MEDIA_REASON_UNSAFE_DELETE_BLOCKED,
                    "reason_code": _MIGRATION_MEDIA_REASON_UNSAFE_DELETE_BLOCKED,
                    "media_asset": self._to_media_asset_read_payload(
                        business_id=business_id,
                        site_id=site_id,
                        media_asset=target_asset,
                    ),
                }
            if current_workspace_status == _MIGRATION_MEDIA_WORKSPACE_STATUS_IGNORED:
                return {
                    "asset_id": target_asset_id,
                    "status": _MIGRATION_MEDIA_REASON_ALREADY_REMOVED,
                    "reason_code": _MIGRATION_MEDIA_REASON_ALREADY_REMOVED,
                    "media_asset": self._to_media_asset_read_payload(
                        business_id=business_id,
                        site_id=site_id,
                        media_asset=target_asset,
                    ),
                }
            target_asset["workspace_status"] = _MIGRATION_MEDIA_WORKSPACE_STATUS_IGNORED
            target_asset["selected_for_draft"] = False
            target_asset["import_status"] = "ignored"
            source_snapshot["discovered_images"] = discovered_assets
            workspace.imported_source_snapshot_json = source_snapshot
            enriched = _normalize_json_dict(workspace.enriched_content_notes_json)
            enriched["workspace_media_assets"] = operator_assets
            workspace.enriched_content_notes_json = enriched
            workspace.updated_by_principal_id = principal_id
            self.seo_migration_repository.save_workspace(workspace)
            self.session.commit()
            self.session.refresh(workspace)
            return {
                "asset_id": target_asset_id,
                "status": _MIGRATION_MEDIA_REASON_IGNORED,
                "reason_code": _MIGRATION_MEDIA_REASON_IGNORED,
                "media_asset": self._to_media_asset_read_payload(
                    business_id=business_id,
                    site_id=site_id,
                    media_asset=target_asset,
                ),
            }

        if current_workspace_status == _MIGRATION_MEDIA_WORKSPACE_STATUS_REMOVED:
            return {
                "asset_id": target_asset_id,
                "status": _MIGRATION_MEDIA_REASON_ALREADY_REMOVED,
                "reason_code": _MIGRATION_MEDIA_REASON_ALREADY_REMOVED,
                "media_asset": self._to_media_asset_read_payload(
                    business_id=business_id,
                    site_id=site_id,
                    media_asset=target_asset,
                ),
            }
        if is_discovered and not is_imported:
            return {
                "asset_id": target_asset_id,
                "status": _MIGRATION_MEDIA_REASON_UNSAFE_DELETE_BLOCKED,
                "reason_code": _MIGRATION_MEDIA_REASON_UNSAFE_DELETE_BLOCKED,
                "media_asset": self._to_media_asset_read_payload(
                    business_id=business_id,
                    site_id=site_id,
                    media_asset=target_asset,
                ),
            }

        target_asset["workspace_status"] = _MIGRATION_MEDIA_WORKSPACE_STATUS_REMOVED
        target_asset["selected_for_draft"] = False
        target_asset["import_status"] = "removed"
        source_snapshot["discovered_images"] = discovered_assets
        workspace.imported_source_snapshot_json = source_snapshot
        enriched = _normalize_json_dict(workspace.enriched_content_notes_json)
        enriched["workspace_media_assets"] = operator_assets
        workspace.enriched_content_notes_json = enriched
        workspace.updated_by_principal_id = principal_id
        self.seo_migration_repository.save_workspace(workspace)
        self.session.commit()
        self.session.refresh(workspace)
        return {
            "asset_id": target_asset_id,
            "status": _MIGRATION_MEDIA_REASON_REMOVED,
            "reason_code": _MIGRATION_MEDIA_REASON_REMOVED,
            "media_asset": self._to_media_asset_read_payload(
                business_id=business_id,
                site_id=site_id,
                media_asset=target_asset,
            ),
        }

    def suggest_media_asset_metadata(
        self,
        *,
        business_id: str,
        site_id: str,
        asset_id: str,
        force_refresh: bool,
        principal_id: str | None,
    ) -> dict[str, object]:
        workspace = self.get_workspace(business_id=business_id, site_id=site_id)
        self._require_site(business_id=business_id, site_id=site_id)
        target_asset_id = _normalize_string(asset_id, max_length=80)
        if target_asset_id is None:
            raise SEOMigrationValidationError(
                "media asset id is required.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code="media_asset_id_required",
                workspace_id=workspace.id,
            )

        source_snapshot = _normalize_json_dict(workspace.imported_source_snapshot_json)
        discovered_assets = _normalize_workspace_discovered_media_assets(source_snapshot.get("discovered_images"))
        operator_assets = _normalize_workspace_operator_media_assets(workspace.enriched_content_notes_json)
        target_asset: dict[str, object] | None = None
        target_collection: list[dict[str, object]] | None = None

        for collection in (discovered_assets, operator_assets):
            for item in collection:
                if _normalize_string(item.get("asset_id"), max_length=80) != target_asset_id:
                    continue
                target_asset = item
                target_collection = collection
                break
            if target_asset is not None:
                break

        if target_asset is None or target_collection is None:
            raise SEOMigrationNotFoundError("Migration media asset not found")
        if not _is_workspace_media_asset_visible(target_asset):
            raise SEOMigrationValidationError(
                "This media asset is no longer available in the active workspace list.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code=_MIGRATION_MEDIA_REASON_ALREADY_REMOVED,
                workspace_id=workspace.id,
            )

        existing_suggestion = _normalize_media_metadata_suggestion(target_asset.get("metadata_suggestion"))
        if (
            not force_refresh
            and existing_suggestion.get("suggestion_status") == _MIGRATION_MEDIA_SUGGESTION_STATUS_COMPLETED
        ):
            return self._to_media_asset_read_payload(
                business_id=business_id,
                site_id=site_id,
                media_asset=target_asset,
            )

        suggestion_payload = self._generate_media_metadata_suggestion_for_asset(
            business_id=business_id,
            site_id=site_id,
            workspace=workspace,
            media_asset=target_asset,
        )
        target_asset["metadata_suggestion"] = suggestion_payload

        source_snapshot["discovered_images"] = discovered_assets
        workspace.imported_source_snapshot_json = source_snapshot
        enriched = _normalize_json_dict(workspace.enriched_content_notes_json)
        enriched["workspace_media_assets"] = operator_assets
        workspace.enriched_content_notes_json = enriched
        workspace.updated_by_principal_id = principal_id
        self.seo_migration_repository.save_workspace(workspace)
        self.session.commit()
        self.session.refresh(workspace)
        return self._to_media_asset_read_payload(
            business_id=business_id,
            site_id=site_id,
            media_asset=target_asset,
        )

    def suggest_media_assets_metadata_batch(
        self,
        *,
        business_id: str,
        site_id: str,
        asset_ids: list[str],
        force_refresh: bool,
        principal_id: str | None,
    ) -> dict[str, object]:
        workspace = self.get_workspace(business_id=business_id, site_id=site_id)
        self._require_site(business_id=business_id, site_id=site_id)

        normalized_asset_ids: list[str] = []
        seen_ids: set[str] = set()
        for raw_asset_id in asset_ids:
            asset_id = _normalize_string(raw_asset_id, max_length=80)
            if asset_id is None:
                continue
            lowered = asset_id.lower()
            if lowered in seen_ids:
                continue
            seen_ids.add(lowered)
            normalized_asset_ids.append(asset_id)

        if not normalized_asset_ids:
            raise SEOMigrationValidationError(
                "At least one media asset id is required for batch suggestion.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code="media_asset_ids_required",
                workspace_id=workspace.id,
            )
        if len(normalized_asset_ids) > _MIGRATION_MEDIA_SUGGESTION_BATCH_MAX_COUNT:
            raise SEOMigrationValidationError(
                "Batch metadata suggestion exceeds the allowed asset count.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code=_MIGRATION_MEDIA_REASON_BATCH_LIMIT_REACHED,
                workspace_id=workspace.id,
            )

        source_snapshot = _normalize_json_dict(workspace.imported_source_snapshot_json)
        discovered_assets = _normalize_workspace_discovered_media_assets(source_snapshot.get("discovered_images"))
        operator_assets = _normalize_workspace_operator_media_assets(workspace.enriched_content_notes_json)

        asset_lookup: dict[str, dict[str, object]] = {}
        for item in [*discovered_assets, *operator_assets]:
            asset_id = _normalize_string(item.get("asset_id"), max_length=80)
            if asset_id is None:
                continue
            asset_lookup[asset_id] = item

        results: list[dict[str, object]] = []
        completed_count = 0
        failed_count = 0
        skipped_count = 0
        mutated = False

        for asset_id in normalized_asset_ids:
            target_asset = asset_lookup.get(asset_id)
            if target_asset is None:
                failed_count += 1
                results.append(
                    {
                        "asset_id": asset_id,
                        "suggestion_status": _MIGRATION_MEDIA_SUGGESTION_STATUS_FAILED,
                        "reason_code": _MIGRATION_MEDIA_REASON_ASSET_NOT_AUTHORIZED,
                        "retryable": False,
                        "metadata_suggestion": None,
                    }
                )
                continue
            if not _is_workspace_media_asset_visible(target_asset):
                failed_count += 1
                results.append(
                    {
                        "asset_id": asset_id,
                        "suggestion_status": _MIGRATION_MEDIA_SUGGESTION_STATUS_FAILED,
                        "reason_code": _MIGRATION_MEDIA_REASON_ASSET_NOT_AUTHORIZED,
                        "retryable": False,
                        "metadata_suggestion": None,
                    }
                )
                continue

            if not bool(target_asset.get("selected_for_draft")):
                skipped_count += 1
                results.append(
                    {
                        "asset_id": asset_id,
                        "suggestion_status": _MIGRATION_MEDIA_SUGGESTION_STATUS_NOT_AVAILABLE,
                        "reason_code": _MIGRATION_MEDIA_REASON_ANALYSIS_NOT_AVAILABLE,
                        "retryable": False,
                        "metadata_suggestion": None,
                    }
                )
                continue

            unusable_reason = _media_asset_unusable_reason_code(target_asset)
            if unusable_reason is not None:
                skipped_count += 1
                results.append(
                    {
                        "asset_id": asset_id,
                        "suggestion_status": _MIGRATION_MEDIA_SUGGESTION_STATUS_NOT_AVAILABLE,
                        "reason_code": unusable_reason,
                        "retryable": False,
                        "metadata_suggestion": None,
                    }
                )
                continue

            suggestion_payload: dict[str, object]
            existing_suggestion = _normalize_media_metadata_suggestion(target_asset.get("metadata_suggestion"))
            if (
                not force_refresh
                and existing_suggestion.get("suggestion_status") == _MIGRATION_MEDIA_SUGGESTION_STATUS_COMPLETED
            ):
                suggestion_payload = existing_suggestion
            else:
                suggestion_payload = self._generate_media_metadata_suggestion_for_asset(
                    business_id=business_id,
                    site_id=site_id,
                    workspace=workspace,
                    media_asset=target_asset,
                )
                target_asset["metadata_suggestion"] = suggestion_payload
                mutated = True

            normalized_suggestion = _normalize_media_metadata_suggestion(suggestion_payload)
            suggestion_status = (
                _normalize_string(normalized_suggestion.get("suggestion_status"), max_length=40)
                or _MIGRATION_MEDIA_SUGGESTION_STATUS_FAILED
            )
            reason_code = _normalize_string(normalized_suggestion.get("reason_code"), max_length=80)
            if suggestion_status == _MIGRATION_MEDIA_SUGGESTION_STATUS_COMPLETED:
                completed_count += 1
            elif suggestion_status == _MIGRATION_MEDIA_SUGGESTION_STATUS_NOT_AVAILABLE:
                skipped_count += 1
            else:
                failed_count += 1

            results.append(
                {
                    "asset_id": asset_id,
                    "suggestion_status": suggestion_status,
                    "reason_code": reason_code,
                    "retryable": _is_media_suggestion_retryable_reason(
                        suggestion_status=suggestion_status,
                        reason_code=reason_code,
                    ),
                    "metadata_suggestion": normalized_suggestion,
                }
            )

        if mutated:
            source_snapshot["discovered_images"] = discovered_assets
            workspace.imported_source_snapshot_json = source_snapshot
            enriched = _normalize_json_dict(workspace.enriched_content_notes_json)
            enriched["workspace_media_assets"] = operator_assets
            workspace.enriched_content_notes_json = enriched
            workspace.updated_by_principal_id = principal_id
            self.seo_migration_repository.save_workspace(workspace)
            self.session.commit()
            self.session.refresh(workspace)

        batch_status = _MIGRATION_MEDIA_SUGGESTION_BATCH_STATUS_FAILED
        if completed_count > 0 and failed_count == 0 and skipped_count == 0:
            batch_status = _MIGRATION_MEDIA_SUGGESTION_BATCH_STATUS_COMPLETED
        elif completed_count > 0:
            batch_status = _MIGRATION_MEDIA_SUGGESTION_BATCH_STATUS_PARTIAL_SUCCESS

        return {
            "batch_status": batch_status,
            "results": results,
            "completed_count": completed_count,
            "failed_count": failed_count,
            "skipped_count": skipped_count,
        }

    def _generate_media_metadata_suggestion_for_asset(
        self,
        *,
        business_id: str,
        site_id: str,
        workspace: SEOMigrationWorkspace,
        media_asset: dict[str, object],
    ) -> dict[str, object]:
        asset_id = _normalize_string(media_asset.get("asset_id"), max_length=80)
        if asset_id is None:
            return _build_media_metadata_suggestion_payload(
                suggestion_status=_MIGRATION_MEDIA_SUGGESTION_STATUS_FAILED,
                reason_code=_MIGRATION_MEDIA_REASON_ASSET_NOT_FOUND,
            )
        provenance = _normalize_string(media_asset.get("provenance"), max_length=40) or "source_site_import"
        content_type = _normalize_media_content_type(media_asset.get("content_type"))
        if content_type is not None and content_type not in _MIGRATION_MEDIA_UPLOAD_ALLOWED_CONTENT_TYPES:
            return _build_media_metadata_suggestion_payload(
                suggestion_status=_MIGRATION_MEDIA_SUGGESTION_STATUS_FAILED,
                reason_code=_MIGRATION_MEDIA_REASON_UNSUPPORTED_IMAGE_TYPE,
            )
        unusable_reason = _media_asset_unusable_reason_code(media_asset)
        if unusable_reason is not None:
            reason_code = (
                _MIGRATION_MEDIA_REASON_IMAGE_NOT_IMPORTED
                if unusable_reason == _MIGRATION_MEDIA_REASON_ASSET_NOT_IMPORTED
                else unusable_reason
            )
            return _build_media_metadata_suggestion_payload(
                suggestion_status=_MIGRATION_MEDIA_SUGGESTION_STATUS_NOT_AVAILABLE,
                reason_code=reason_code,
            )
        storage_key = _normalize_string(media_asset.get("storage_key"), max_length=240)
        if storage_key is None:
            return _build_media_metadata_suggestion_payload(
                suggestion_status=_MIGRATION_MEDIA_SUGGESTION_STATUS_NOT_AVAILABLE,
                reason_code=_MIGRATION_MEDIA_REASON_ANALYSIS_NOT_AVAILABLE,
            )

        try:
            image_bytes = _read_workspace_media_file(
                storage_root=self.media_storage_root,
                storage_key=storage_key,
            )
        except SEOMigrationValidationError:
            return _build_media_metadata_suggestion_payload(
                suggestion_status=_MIGRATION_MEDIA_SUGGESTION_STATUS_NOT_AVAILABLE,
                reason_code=_MIGRATION_MEDIA_REASON_ANALYSIS_NOT_AVAILABLE,
            )

        if not image_bytes:
            return _build_media_metadata_suggestion_payload(
                suggestion_status=_MIGRATION_MEDIA_SUGGESTION_STATUS_NOT_AVAILABLE,
                reason_code=_MIGRATION_MEDIA_REASON_ANALYSIS_NOT_AVAILABLE,
            )
        if len(image_bytes) > _MIGRATION_MEDIA_SUGGESTION_MAX_BYTES:
            return _build_media_metadata_suggestion_payload(
                suggestion_status=_MIGRATION_MEDIA_SUGGESTION_STATUS_FAILED,
                reason_code=_MIGRATION_MEDIA_REASON_IMAGE_TOO_LARGE,
            )
        sniffed_content_type = _detect_media_content_type(image_bytes)
        if sniffed_content_type not in _MIGRATION_MEDIA_UPLOAD_ALLOWED_CONTENT_TYPES:
            return _build_media_metadata_suggestion_payload(
                suggestion_status=_MIGRATION_MEDIA_SUGGESTION_STATUS_FAILED,
                reason_code=_MIGRATION_MEDIA_REASON_UNSUPPORTED_IMAGE_TYPE,
            )

        provider_payload = {
            "asset_id": asset_id,
            "business_id": business_id,
            "site_id": site_id,
            "workspace_id": workspace.id,
            "display_filename": _normalize_string(
                media_asset.get("display_filename") or media_asset.get("filename"),
                max_length=160,
            ),
            "provenance": provenance,
            "category": _normalize_media_category(media_asset.get("category")),
            "alt_text": _normalize_string(media_asset.get("alt_text"), max_length=240),
            "description": _normalize_string(media_asset.get("description"), max_length=800),
            "usage_note": _normalize_string(media_asset.get("usage_note"), max_length=400),
            "page_assignment": _normalize_string(media_asset.get("page_assignment"), max_length=120),
        }
        try:
            suggestion = self._request_media_metadata_suggestion(
                image_bytes=image_bytes,
                content_type=sniffed_content_type,
                asset_metadata=provider_payload,
            )
        except SEOMigrationValidationError as exc:
            reason_code = (
                _normalize_string(exc.error_code, max_length=80) or _MIGRATION_MEDIA_REASON_PROVIDER_UNAVAILABLE
            )
            suggestion_status = (
                _MIGRATION_MEDIA_SUGGESTION_STATUS_NOT_AVAILABLE
                if reason_code == _MIGRATION_MEDIA_REASON_ANALYSIS_NOT_AVAILABLE
                else _MIGRATION_MEDIA_SUGGESTION_STATUS_FAILED
            )
            return _build_media_metadata_suggestion_payload(
                suggestion_status=suggestion_status,
                reason_code=reason_code,
            )

        return _build_media_metadata_suggestion_payload(
            suggestion_status=_MIGRATION_MEDIA_SUGGESTION_STATUS_COMPLETED,
            reason_code=_MIGRATION_MEDIA_REASON_SUGGESTED,
            suggested_category=suggestion.get("suggested_category"),
            suggested_alt_text=suggestion.get("suggested_alt_text"),
            suggested_description=suggestion.get("suggested_description"),
            suggested_usage_note=suggestion.get("suggested_usage_note"),
            suggested_page_assignment=suggestion.get("suggested_page_assignment"),
            confidence=suggestion.get("confidence"),
        )

    def import_selected_discovered_media_assets(
        self,
        *,
        business_id: str,
        site_id: str,
        principal_id: str | None,
    ) -> dict[str, object]:
        workspace = self.get_workspace(business_id=business_id, site_id=site_id)
        source_snapshot = _normalize_json_dict(workspace.imported_source_snapshot_json)
        discovered_assets = _normalize_workspace_discovered_media_assets(source_snapshot.get("discovered_images"))
        selected_asset_ids: list[str] = []
        seen_asset_ids: set[str] = set()
        for item in discovered_assets:
            if not bool(item.get("selected_for_draft")):
                continue
            if _normalize_string(item.get("provenance"), max_length=40) != "source_site_import":
                continue
            asset_id = _normalize_string(item.get("asset_id"), max_length=80)
            if asset_id is None:
                continue
            lowered = asset_id.lower()
            if lowered in seen_asset_ids:
                continue
            seen_asset_ids.add(lowered)
            selected_asset_ids.append(asset_id)
        import_result = self.import_discovered_media_assets(
            business_id=business_id,
            site_id=site_id,
            discovered_image_ids=selected_asset_ids,
            normalized_urls=[],
            selected_for_draft=True,
            principal_id=principal_id,
        )
        failures = []
        for item in _coerce_object_list(import_result.get("results"), max_items=200):
            status_value = (_normalize_string(item.get("status"), max_length=40) or "").lower()
            if status_value not in {"failed", "disabled"}:
                continue
            failures.append(
                {
                    "asset_id": _normalize_string(item.get("asset_id"), max_length=80),
                    "reason_code": _normalize_string(item.get("reason_code"), max_length=80),
                }
            )
        return {
            "implemented": self.remote_image_import_enabled,
            "attempted_count": len(selected_asset_ids),
            "imported_count": max(0, int(import_result.get("imported_count") or 0)),
            "failure_reason_code": (
                _MIGRATION_MEDIA_REASON_REMOTE_IMPORT_DISABLED if not self.remote_image_import_enabled else None
            ),
            "failures": failures,
            "results": _coerce_object_list(import_result.get("results"), max_items=200),
        }

    def import_discovered_media_assets(
        self,
        *,
        business_id: str,
        site_id: str,
        discovered_image_ids: list[str],
        normalized_urls: list[str],
        selected_for_draft: bool | None,
        allow_quality_override: bool = False,
        principal_id: str | None,
    ) -> dict[str, object]:
        workspace = self.get_workspace(business_id=business_id, site_id=site_id)
        self._require_site(business_id=business_id, site_id=site_id)

        normalized_asset_ids: list[str] = []
        seen_input_keys: set[str] = set()
        for raw_asset_id in discovered_image_ids:
            asset_id = _normalize_string(raw_asset_id, max_length=80)
            if asset_id is None:
                continue
            key = f"id:{asset_id.lower()}"
            if key in seen_input_keys:
                continue
            seen_input_keys.add(key)
            normalized_asset_ids.append(asset_id)

        normalized_lookup_urls: list[str] = []
        for raw_url in normalized_urls:
            normalized_url = _normalize_discovered_media_lookup_url(raw_url)
            if normalized_url is None:
                continue
            key = f"url:{normalized_url.lower()}"
            if key in seen_input_keys:
                continue
            seen_input_keys.add(key)
            normalized_lookup_urls.append(normalized_url)

        requested_items: list[dict[str, str | None]] = [
            {"asset_id": asset_id, "normalized_url": None} for asset_id in normalized_asset_ids
        ]
        requested_items.extend(
            {"asset_id": None, "normalized_url": normalized_url} for normalized_url in normalized_lookup_urls
        )

        if not requested_items:
            raise SEOMigrationValidationError(
                "At least one discovered media identifier is required for import.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code="discovered_image_ids_required",
                workspace_id=workspace.id,
            )
        if len(requested_items) > _MIGRATION_MEDIA_IMPORT_BATCH_MAX_COUNT:
            raise SEOMigrationValidationError(
                "Discovered media import exceeds the allowed asset count per request.",
                failure_category="artifact_invalid",
                failure_reason="validation_failed",
                error_code=_MIGRATION_MEDIA_REASON_IMPORT_COUNT_LIMIT_REACHED,
                workspace_id=workspace.id,
            )

        if not self.remote_image_import_enabled:
            results = [
                {
                    "asset_id": item["asset_id"],
                    "normalized_url": item["normalized_url"],
                    "status": "disabled",
                    "reason_code": _MIGRATION_MEDIA_REASON_REMOTE_IMPORT_DISABLED,
                    "media_asset": None,
                }
                for item in requested_items
            ]
            return {
                "batch_status": _MIGRATION_MEDIA_IMPORT_BATCH_STATUS_FAILED,
                "results": results,
                "imported_count": 0,
                "failed_count": 0,
                "skipped_count": 0,
                "disabled_count": len(results),
            }

        source_snapshot = _normalize_json_dict(workspace.imported_source_snapshot_json)
        discovered_assets = _normalize_workspace_discovered_media_assets(source_snapshot.get("discovered_images"))
        discovered_by_asset_id: dict[str, dict[str, object]] = {}
        discovered_by_url: dict[str, dict[str, object]] = {}
        for item in discovered_assets:
            asset_id = _normalize_string(item.get("asset_id"), max_length=80)
            if asset_id is not None:
                discovered_by_asset_id[asset_id.lower()] = item
            normalized_url = _normalize_discovered_media_lookup_url(item.get("normalized_url"))
            if normalized_url is not None:
                discovered_by_url[normalized_url.lower()] = item

        current_imported_count = sum(1 for item in discovered_assets if _is_discovered_media_asset_imported(item))
        mutated = False
        imported_count = 0
        failed_count = 0
        skipped_count = 0
        disabled_count = 0
        results: list[dict[str, object]] = []
        resolved_assets_seen: set[str] = set()
        for requested in requested_items:
            request_asset_id = _normalize_string(requested.get("asset_id"), max_length=80)
            request_url = _normalize_discovered_media_lookup_url(requested.get("normalized_url"))
            target_asset: dict[str, object] | None = None
            if request_asset_id is not None:
                target_asset = discovered_by_asset_id.get(request_asset_id.lower())
            if target_asset is None and request_url is not None:
                target_asset = discovered_by_url.get(request_url.lower())
            if target_asset is None:
                failed_count += 1
                results.append(
                    {
                        "asset_id": request_asset_id,
                        "normalized_url": request_url,
                        "status": "failed",
                        "reason_code": _MIGRATION_MEDIA_REASON_IMAGE_NOT_FOUND_IN_SOURCE_SNAPSHOT,
                        "media_asset": None,
                    }
                )
                continue

            target_asset_id = _normalize_string(target_asset.get("asset_id"), max_length=80)
            if target_asset_id is None:
                failed_count += 1
                results.append(
                    {
                        "asset_id": request_asset_id,
                        "normalized_url": request_url,
                        "status": "failed",
                        "reason_code": _MIGRATION_MEDIA_REASON_IMAGE_NOT_FOUND_IN_SOURCE_SNAPSHOT,
                        "media_asset": None,
                    }
                )
                continue
            if not _is_workspace_media_asset_visible(target_asset):
                failed_count += 1
                results.append(
                    {
                        "asset_id": target_asset_id,
                        "normalized_url": _normalize_discovered_media_lookup_url(target_asset.get("normalized_url")),
                        "status": "failed",
                        "reason_code": _MIGRATION_MEDIA_REASON_IMAGE_NOT_FOUND_IN_SOURCE_SNAPSHOT,
                        "media_asset": None,
                    }
                )
                continue
            target_asset_key = target_asset_id.lower()
            if target_asset_key in resolved_assets_seen:
                skipped_count += 1
                results.append(
                    {
                        "asset_id": target_asset_id,
                        "normalized_url": _normalize_discovered_media_lookup_url(target_asset.get("normalized_url")),
                        "status": "skipped",
                        "reason_code": _MIGRATION_MEDIA_REASON_REMOTE_IMAGE_IMPORTED,
                        "media_asset": self._to_media_asset_read_payload(
                            business_id=business_id,
                            site_id=site_id,
                            media_asset=target_asset,
                        ),
                    }
                )
                continue
            resolved_assets_seen.add(target_asset_key)

            provenance = _normalize_string(target_asset.get("provenance"), max_length=40) or "source_site_import"
            if provenance != "source_site_import":
                failed_count += 1
                results.append(
                    {
                        "asset_id": target_asset_id,
                        "normalized_url": _normalize_discovered_media_lookup_url(target_asset.get("normalized_url")),
                        "status": "failed",
                        "reason_code": _MIGRATION_MEDIA_REASON_ASSET_NOT_AUTHORIZED,
                        "media_asset": None,
                    }
                )
                continue

            candidate_quality = _normalize_media_candidate_quality(target_asset.get("candidate_quality"))
            quality_reason = _normalize_media_quality_reason(target_asset.get("quality_reason"))
            if candidate_quality == _MIGRATION_MEDIA_CANDIDATE_QUALITY_REJECTED:
                failed_count += 1
                results.append(
                    {
                        "asset_id": target_asset_id,
                        "normalized_url": _normalize_discovered_media_lookup_url(target_asset.get("normalized_url")),
                        "status": "failed",
                        "reason_code": quality_reason or _MIGRATION_MEDIA_REASON_ASSET_REJECTED,
                        "media_asset": None,
                    }
                )
                continue
            if candidate_quality == _MIGRATION_MEDIA_CANDIDATE_QUALITY_LOW_VALUE:
                if not allow_quality_override:
                    failed_count += 1
                    results.append(
                        {
                            "asset_id": target_asset_id,
                            "normalized_url": _normalize_discovered_media_lookup_url(target_asset.get("normalized_url")),
                            "status": "failed",
                            "reason_code": quality_reason or _MIGRATION_MEDIA_REASON_ASSET_LOW_VALUE,
                            "media_asset": None,
                        }
                    )
                    continue
                if not _is_discovered_media_quality_override_allowed(target_asset):
                    failed_count += 1
                    results.append(
                        {
                            "asset_id": target_asset_id,
                            "normalized_url": _normalize_discovered_media_lookup_url(target_asset.get("normalized_url")),
                            "status": "failed",
                            "reason_code": quality_reason or _MIGRATION_MEDIA_REASON_ASSET_REJECTED,
                            "media_asset": None,
                        }
                    )
                    continue

            if _is_discovered_media_asset_imported(target_asset):
                selected_value = (
                    bool(selected_for_draft)
                    if isinstance(selected_for_draft, bool)
                    else bool(target_asset.get("selected_for_draft"))
                )
                target_asset["selected_for_draft"] = selected_value
                target_asset["import_status"] = "selected" if selected_value else "imported"
                skipped_count += 1
                mutated = True
                results.append(
                    {
                        "asset_id": target_asset_id,
                        "normalized_url": _normalize_discovered_media_lookup_url(target_asset.get("normalized_url")),
                        "status": "skipped",
                        "reason_code": _MIGRATION_MEDIA_REASON_REMOTE_IMAGE_IMPORTED,
                        "media_asset": self._to_media_asset_read_payload(
                            business_id=business_id,
                            site_id=site_id,
                            media_asset=target_asset,
                        ),
                    }
                )
                continue

            if not _is_discovered_media_candidate_validated_for_import(target_asset):
                failed_count += 1
                results.append(
                    {
                        "asset_id": target_asset_id,
                        "normalized_url": _normalize_discovered_media_lookup_url(target_asset.get("normalized_url")),
                        "status": "failed",
                        "reason_code": _MIGRATION_MEDIA_REASON_CANDIDATE_NOT_VALIDATED,
                        "media_asset": None,
                    }
                )
                continue

            if current_imported_count >= _MIGRATION_MEDIA_IMPORT_MAX_TOTAL_IMPORTED:
                failed_count += 1
                results.append(
                    {
                        "asset_id": target_asset_id,
                        "normalized_url": _normalize_discovered_media_lookup_url(target_asset.get("normalized_url")),
                        "status": "failed",
                        "reason_code": _MIGRATION_MEDIA_REASON_IMPORT_COUNT_LIMIT_REACHED,
                        "media_asset": None,
                    }
                )
                continue

            fetch_result = self._fetch_remote_discovered_image_for_import(
                url=(
                    _normalize_discovered_media_lookup_url(target_asset.get("normalized_url"))
                    or _normalize_string(target_asset.get("normalized_url"), max_length=2048)
                    or ""
                ),
            )
            fetch_reason_code = _normalize_import_reason_code(fetch_result.get("reason_code"))
            if fetch_reason_code != _MIGRATION_MEDIA_REASON_REMOTE_IMAGE_IMPORTED:
                failed_count += 1
                results.append(
                    {
                        "asset_id": target_asset_id,
                        "normalized_url": _normalize_discovered_media_lookup_url(target_asset.get("normalized_url")),
                        "status": "failed",
                        "reason_code": fetch_reason_code or _MIGRATION_MEDIA_REASON_IMAGE_FETCH_FAILED,
                        "media_asset": None,
                    }
                )
                continue

            payload = fetch_result.get("payload")
            detected_content_type = _normalize_media_content_type(fetch_result.get("content_type"))
            if not isinstance(payload, bytes) or not payload:
                failed_count += 1
                results.append(
                    {
                        "asset_id": target_asset_id,
                        "normalized_url": _normalize_discovered_media_lookup_url(target_asset.get("normalized_url")),
                        "status": "failed",
                        "reason_code": _MIGRATION_MEDIA_REASON_IMAGE_FETCH_FAILED,
                        "media_asset": None,
                    }
                )
                continue
            if detected_content_type not in _MIGRATION_MEDIA_UPLOAD_ALLOWED_CONTENT_TYPES:
                failed_count += 1
                results.append(
                    {
                        "asset_id": target_asset_id,
                        "normalized_url": _normalize_discovered_media_lookup_url(target_asset.get("normalized_url")),
                        "status": "failed",
                        "reason_code": _MIGRATION_MEDIA_REASON_UNSUPPORTED_CONTENT_TYPE,
                        "media_asset": None,
                    }
                )
                continue

            extension = _MIGRATION_MEDIA_UPLOAD_ALLOWED_CONTENT_TYPES.get(detected_content_type, "")
            storage_key = _build_workspace_media_storage_key(
                business_id=business_id,
                site_id=site_id,
                asset_id=target_asset_id,
                extension=extension,
            )
            try:
                _write_workspace_media_file(
                    storage_root=self.media_storage_root,
                    storage_key=storage_key,
                    payload=payload,
                )
            except OSError:
                failed_count += 1
                results.append(
                    {
                        "asset_id": target_asset_id,
                        "normalized_url": _normalize_discovered_media_lookup_url(target_asset.get("normalized_url")),
                        "status": "failed",
                        "reason_code": _MIGRATION_MEDIA_REASON_STORAGE_WRITE_FAILED,
                        "media_asset": None,
                    }
                )
                continue
            width, height = _detect_image_dimensions(payload, detected_content_type)
            normalized_final_url = _normalize_discovered_media_lookup_url(fetch_result.get("final_url"))
            selected_value = (
                bool(selected_for_draft)
                if isinstance(selected_for_draft, bool)
                else bool(target_asset.get("selected_for_draft"))
            )
            target_asset["display_filename"] = (
                _normalize_media_filename(target_asset.get("display_filename"))
                or _normalize_media_filename(target_asset.get("filename"))
                or _safe_media_filename_from_url(normalized_final_url or "")
            )
            target_asset["content_type"] = detected_content_type
            target_asset["size_bytes"] = len(payload)
            target_asset["width"] = width
            target_asset["height"] = height
            target_asset["storage_key"] = storage_key
            target_asset["import_status"] = "selected" if selected_value else "imported"
            target_asset["selected_for_draft"] = selected_value
            target_asset["normalized_url"] = normalized_final_url or _normalize_discovered_media_lookup_url(
                target_asset.get("normalized_url")
            )
            target_asset["source_page_url"] = _normalize_discovered_media_lookup_url(
                target_asset.get("source_page_url")
            )
            target_asset["created_at"] = (
                _normalize_string(target_asset.get("created_at"), max_length=80) or utc_now().isoformat()
            )
            suggestion = _normalize_media_metadata_suggestion(target_asset.get("metadata_suggestion"))
            if suggestion.get("reason_code") in {
                _MIGRATION_MEDIA_REASON_IMAGE_NOT_IMPORTED,
                _MIGRATION_MEDIA_REASON_ASSET_NOT_IMPORTED,
            }:
                target_asset["metadata_suggestion"] = None
                target_asset["metadata_suggestion_applied"] = False
                target_asset["metadata_suggestion_applied_at"] = None
            current_imported_count += 1
            imported_count += 1
            mutated = True
            results.append(
                {
                    "asset_id": target_asset_id,
                    "normalized_url": _normalize_discovered_media_lookup_url(target_asset.get("normalized_url")),
                    "status": "imported",
                    "reason_code": _MIGRATION_MEDIA_REASON_REMOTE_IMAGE_IMPORTED,
                    "media_asset": self._to_media_asset_read_payload(
                        business_id=business_id,
                        site_id=site_id,
                        media_asset=target_asset,
                    ),
                }
            )

        if mutated:
            source_snapshot["discovered_images"] = discovered_assets
            workspace.imported_source_snapshot_json = source_snapshot
            workspace.updated_by_principal_id = principal_id
            self.seo_migration_repository.save_workspace(workspace)
            self.session.commit()
            self.session.refresh(workspace)

        batch_status = _MIGRATION_MEDIA_IMPORT_BATCH_STATUS_FAILED
        if failed_count == 0 and disabled_count == 0:
            batch_status = _MIGRATION_MEDIA_IMPORT_BATCH_STATUS_COMPLETED
        elif imported_count > 0 or skipped_count > 0:
            batch_status = _MIGRATION_MEDIA_IMPORT_BATCH_STATUS_PARTIAL_SUCCESS

        return {
            "batch_status": batch_status,
            "results": results,
            "imported_count": imported_count,
            "failed_count": failed_count,
            "skipped_count": skipped_count,
            "disabled_count": disabled_count,
        }

    def _fetch_remote_discovered_image_for_import(self, *, url: str) -> dict[str, object]:
        current_url = _normalize_discovered_media_lookup_url(url) or ""
        if not current_url:
            return {
                "reason_code": _MIGRATION_MEDIA_REASON_CANDIDATE_NOT_VALIDATED,
            }
        opener = urllib.request.build_opener(_SEOMediaImportNoRedirectHandler())
        redirect_count = 0
        while True:
            safety_reason = _validate_remote_image_import_url(current_url)
            if safety_reason is not None:
                return {
                    "reason_code": safety_reason,
                }
            request = urllib.request.Request(
                current_url,
                headers={
                    "User-Agent": "MBSRN-Migration-MediaImport/1.0",
                    "Accept": "image/*",
                },
            )
            try:
                with opener.open(request, timeout=_MIGRATION_MEDIA_IMPORT_TIMEOUT_SECONDS) as response:
                    raw_declared_content_type = _normalize_string(response.headers.get("Content-Type"), max_length=120)
                    declared_content_type = _normalize_media_content_type(raw_declared_content_type)
                    if raw_declared_content_type and declared_content_type is None:
                        return {
                            "reason_code": _MIGRATION_MEDIA_REASON_UNSUPPORTED_CONTENT_TYPE,
                        }
                    if (
                        declared_content_type is not None
                        and declared_content_type not in _MIGRATION_MEDIA_UPLOAD_ALLOWED_CONTENT_TYPES
                    ):
                        return {
                            "reason_code": _MIGRATION_MEDIA_REASON_UNSUPPORTED_CONTENT_TYPE,
                        }
                    payload_chunks: list[bytes] = []
                    total_bytes = 0
                    while True:
                        chunk = response.read(64 * 1024)
                        if not chunk:
                            break
                        if not isinstance(chunk, bytes):
                            continue
                        total_bytes += len(chunk)
                        if total_bytes > _MIGRATION_MEDIA_UPLOAD_MAX_BYTES:
                            return {
                                "reason_code": _MIGRATION_MEDIA_REASON_FILE_TOO_LARGE,
                            }
                        payload_chunks.append(chunk)
                    payload = b"".join(payload_chunks)
                    if not payload:
                        return {
                            "reason_code": _MIGRATION_MEDIA_REASON_IMAGE_FETCH_FAILED,
                        }
                    detected_content_type = _detect_media_content_type(payload)
                    if detected_content_type not in _MIGRATION_MEDIA_UPLOAD_ALLOWED_CONTENT_TYPES:
                        return {
                            "reason_code": _MIGRATION_MEDIA_REASON_UNSUPPORTED_CONTENT_TYPE,
                        }
                    if declared_content_type is not None and declared_content_type != detected_content_type:
                        return {
                            "reason_code": _MIGRATION_MEDIA_REASON_UNSUPPORTED_CONTENT_TYPE,
                        }
                    final_url = _normalize_discovered_media_lookup_url(getattr(response, "url", current_url))
                    return {
                        "reason_code": _MIGRATION_MEDIA_REASON_REMOTE_IMAGE_IMPORTED,
                        "payload": payload,
                        "content_type": detected_content_type,
                        "final_url": final_url or current_url,
                    }
            except urllib.error.HTTPError as exc:
                if exc.code in {301, 302, 303, 307, 308}:
                    if redirect_count >= _MIGRATION_MEDIA_IMPORT_MAX_REDIRECTS:
                        return {
                            "reason_code": _MIGRATION_MEDIA_REASON_UNSAFE_REDIRECT,
                        }
                    location = _normalize_string(exc.headers.get("Location") if exc.headers else None, max_length=2048)
                    if location is None:
                        return {
                            "reason_code": _MIGRATION_MEDIA_REASON_UNSAFE_REDIRECT,
                        }
                    current_url = urllib.parse.urljoin(current_url, location)
                    redirect_count += 1
                    continue
                return {
                    "reason_code": _MIGRATION_MEDIA_REASON_IMAGE_FETCH_FAILED,
                }
            except TimeoutError:
                return {
                    "reason_code": _MIGRATION_MEDIA_REASON_FETCH_TIMEOUT,
                }
            except urllib.error.URLError as exc:
                reason_text = str(getattr(exc, "reason", "")).lower()
                if "timed out" in reason_text:
                    return {
                        "reason_code": _MIGRATION_MEDIA_REASON_FETCH_TIMEOUT,
                    }
                return {
                    "reason_code": _MIGRATION_MEDIA_REASON_IMAGE_FETCH_FAILED,
                }

    def ingest_source_snapshot(
        self,
        *,
        business_id: str,
        site_id: str,
        source_url: str | None,
        principal_id: str | None,
    ) -> SEOMigrationWorkspace:
        site = self._require_site(business_id=business_id, site_id=site_id)
        workspace = self.get_workspace(business_id=business_id, site_id=site_id)
        effective_source_url = (source_url or workspace.source_url or "").strip()
        if not effective_source_url:
            raise SEOMigrationValidationError("source_url is required before ingest")

        try:
            ingest_result = self.ingest_service.ingest_homepage(source_url=effective_source_url)
        except SEOMigrationSourceIngestError as exc:
            workspace.source_url = effective_source_url
            workspace.source_site_status = "ingest_failed"
            workspace.migration_status = "source_needs_review"
            workspace.updated_by_principal_id = principal_id
            self._update_workspace_readiness_statuses(workspace=workspace, site=site)
            self.seo_migration_repository.save_workspace(workspace)
            self.session.commit()
            raise SEOMigrationValidationError(str(exc)) from exc

        workspace.source_url = ingest_result.source_url
        workspace.source_site_status = "ingested"
        workspace.migration_status = "source_ingested"
        workspace.imported_source_snapshot_json = ingest_result.snapshot
        workspace.updated_by_principal_id = principal_id
        self._update_workspace_readiness_statuses(workspace=workspace, site=site)
        self.seo_migration_repository.save_workspace(workspace)
        self.session.commit()
        self.session.refresh(workspace)
        return workspace

    def update_operator_requirements(
        self,
        *,
        business_id: str,
        site_id: str,
        operator_requirements: dict[str, object],
        principal_id: str | None,
    ) -> SEOMigrationWorkspace:
        site = self._require_site(business_id=business_id, site_id=site_id)
        workspace = self.get_workspace(business_id=business_id, site_id=site_id)
        workspace.operator_requirements_json = _normalize_json_dict(operator_requirements)
        workspace.updated_by_principal_id = principal_id
        self._update_workspace_readiness_statuses(workspace=workspace, site=site)
        self.seo_migration_repository.save_workspace(workspace)
        self.session.commit()
        self.session.refresh(workspace)
        return workspace

    def suggest_operator_requirement_field(
        self,
        *,
        business_id: str,
        site_id: str,
        field: str,
        current_value: object,
        force_refresh: bool,
        principal_id: str | None,
    ) -> dict[str, object]:
        del force_refresh
        del principal_id
        workspace = self.get_workspace(business_id=business_id, site_id=site_id)
        site = self._require_site(business_id=business_id, site_id=site_id)
        normalized_field = (_normalize_string(field, max_length=80) or "").lower()
        if normalized_field not in _REQUIREMENTS_SUGGESTION_SUPPORTED_FIELDS:
            return {
                "field": normalized_field or "unsupported",
                "suggestion_status": _REQUIREMENTS_SUGGESTION_STATUS_NOT_AVAILABLE,
                "suggested_value": None,
                "reason_code": _REQUIREMENTS_SUGGESTION_REASON_FIELD_UNSUPPORTED,
                "context_sources_used": [],
                "retryable": False,
                "generated_at": None,
            }

        normalized_current_value: str | list[str] | None
        if isinstance(current_value, list):
            normalized_current_value = _normalize_string_list(
                current_value,
                max_items=20,
                max_item_length=240,
            )
        else:
            normalized_current_value = _normalize_string(current_value, max_length=5000)

        try:
            context_json, context_summary = self._assemble_context(site=site, workspace=workspace)
        except Exception:  # noqa: BLE001
            return {
                "field": normalized_field,
                "suggestion_status": _REQUIREMENTS_SUGGESTION_STATUS_FAILED,
                "suggested_value": None,
                "reason_code": _REQUIREMENTS_SUGGESTION_REASON_CONTEXT_UNAVAILABLE,
                "context_sources_used": [],
                "retryable": True,
                "generated_at": None,
            }

        media_assets_payload = self._collect_workspace_media_assets(workspace=workspace)
        suggestion_context, context_sources_used = self._build_requirement_suggestion_context(
            field=normalized_field,
            site=site,
            workspace=workspace,
            context_json=context_json,
            context_summary=context_summary,
            media_assets_payload=media_assets_payload,
        )

        try:
            suggestion_value = self._request_requirement_field_suggestion(
                field=normalized_field,
                current_value=normalized_current_value,
                suggestion_context=suggestion_context,
            )
        except SEOMigrationValidationError as exc:
            error_code = _normalize_string(exc.error_code, max_length=80) or ""
            reason_code = (
                error_code
                if error_code
                in {
                    _REQUIREMENTS_SUGGESTION_REASON_NOT_AVAILABLE,
                    _REQUIREMENTS_SUGGESTION_REASON_PROVIDER_UNAVAILABLE,
                    _REQUIREMENTS_SUGGESTION_REASON_PROVIDER_INVALID,
                    _REQUIREMENTS_SUGGESTION_REASON_CONTEXT_UNAVAILABLE,
                    _REQUIREMENTS_SUGGESTION_REASON_FIELD_UNSUPPORTED,
                    _REQUIREMENTS_SUGGESTION_REASON_BUDGET_REJECTED,
                }
                else _REQUIREMENTS_SUGGESTION_REASON_PROVIDER_UNAVAILABLE
            )
            status_value = (
                _REQUIREMENTS_SUGGESTION_STATUS_NOT_AVAILABLE
                if reason_code
                in {
                    _REQUIREMENTS_SUGGESTION_REASON_NOT_AVAILABLE,
                    _REQUIREMENTS_SUGGESTION_REASON_FIELD_UNSUPPORTED,
                    _REQUIREMENTS_SUGGESTION_REASON_BUDGET_REJECTED,
                }
                else _REQUIREMENTS_SUGGESTION_STATUS_FAILED
            )
            return {
                "field": normalized_field,
                "suggestion_status": status_value,
                "suggested_value": None,
                "reason_code": reason_code,
                "context_sources_used": context_sources_used,
                "retryable": bool(exc.retryable),
                "generated_at": None,
            }

        normalized_suggestion_value = self._normalize_requirement_suggestion_value(
            field=normalized_field,
            value=suggestion_value,
        )
        if normalized_suggestion_value is None:
            return {
                "field": normalized_field,
                "suggestion_status": _REQUIREMENTS_SUGGESTION_STATUS_NOT_AVAILABLE,
                "suggested_value": None,
                "reason_code": _REQUIREMENTS_SUGGESTION_REASON_NOT_AVAILABLE,
                "context_sources_used": context_sources_used,
                "retryable": False,
                "generated_at": None,
            }
        return {
            "field": normalized_field,
            "suggestion_status": _REQUIREMENTS_SUGGESTION_STATUS_COMPLETED,
            "suggested_value": normalized_suggestion_value,
            "reason_code": _REQUIREMENTS_SUGGESTION_REASON_COMPLETED,
            "context_sources_used": context_sources_used,
            "retryable": False,
            "generated_at": utc_now().isoformat(),
        }

    def _build_requirement_suggestion_context(
        self,
        *,
        field: str,
        site: SEOSite,
        workspace: SEOMigrationWorkspace,
        context_json: dict[str, object],
        context_summary: dict[str, object],
        media_assets_payload: dict[str, object],
    ) -> tuple[dict[str, object], list[str]]:
        source_snapshot = _normalize_json_dict(context_json.get("source_snapshot"))
        operator_requirements = _normalize_json_dict(workspace.operator_requirements_json)
        enriched_notes = _normalize_json_dict(workspace.enriched_content_notes_json)
        brand_business_facts = _normalize_json_dict(context_json.get("brand_business_facts_snapshot"))
        draft_input_summary = _normalize_json_dict(context_summary.get("draft_input_summary"))
        existing_context_summaries = _normalize_json_dict(context_json.get("existing_context_summaries"))
        recommendation_summary = _normalize_json_dict(existing_context_summaries.get("recommendation_summary"))
        audit_summary = _normalize_json_dict(existing_context_summaries.get("audit_summary"))
        competitor_summary = _normalize_json_dict(existing_context_summaries.get("competitor_summary"))

        recommendation_titles = _normalize_string_list(
            draft_input_summary.get("top_recommendation_titles"),
            max_items=6,
            max_item_length=180,
        )
        recommendation_categories = _normalize_string_list(
            draft_input_summary.get("recommendation_categories_included"),
            max_items=6,
            max_item_length=80,
        )
        audit_findings: list[str] = []
        for item in _coerce_object_list(audit_summary.get("top_issues"), max_items=6):
            issue_record = _normalize_json_dict(item)
            issue_text = (
                _normalize_string(issue_record.get("title"), max_length=220)
                or _normalize_string(issue_record.get("issue"), max_length=220)
                or _normalize_string(issue_record.get("summary"), max_length=220)
            )
            if issue_text:
                audit_findings.append(issue_text)
        competitor_highlights: list[str] = []
        for item in _coerce_object_list(competitor_summary.get("top_gaps"), max_items=6):
            gap_record = _normalize_json_dict(item)
            gap_text = (
                _normalize_string(gap_record.get("title"), max_length=220)
                or _normalize_string(gap_record.get("gap"), max_length=220)
                or _normalize_string(gap_record.get("summary"), max_length=220)
            )
            if gap_text:
                competitor_highlights.append(gap_text)
        media_categories = _collect_media_categories(
            _normalize_media_asset_list(media_assets_payload.get("selected_assets"), max_items=24),
            max_items=8,
        )
        selected_media_count = max(0, int(media_assets_payload.get("selected_assets_count") or 0))
        selected_usable_media_count = max(
            0,
            int(media_assets_payload.get("selected_usable_assets_count") or 0),
        )
        context_sources_used: list[str] = []
        if source_snapshot:
            context_sources_used.append("source_snapshot")
        if operator_requirements:
            context_sources_used.append("operator_requirements")
        if recommendation_titles or recommendation_categories or recommendation_summary:
            context_sources_used.append("recommendations_summary")
        if audit_findings or audit_summary:
            context_sources_used.append("audit_summary")
        if competitor_highlights or competitor_summary:
            context_sources_used.append("competitor_summary")
        if selected_media_count > 0 or media_categories:
            context_sources_used.append("selected_media_summary")
        if enriched_notes:
            context_sources_used.append("enriched_supporting")
        if brand_business_facts:
            context_sources_used.append("business_site_context")

        suggestion_context: dict[str, object] = {
            "field": field,
            "site": {
                "site_id": site.id,
                "display_name": _normalize_string(site.display_name, max_length=120),
                "normalized_domain": _normalize_string(site.normalized_domain, max_length=255),
                "industry": _normalize_string(site.industry, max_length=160),
                "primary_location": _normalize_string(site.primary_location, max_length=160),
                "service_areas": _normalize_string_list(site.service_areas_json, max_items=8, max_item_length=120),
            },
            "source_snapshot": {
                "title": _normalize_string(source_snapshot.get("title"), max_length=220),
                "meta_description": _normalize_string(source_snapshot.get("meta_description"), max_length=600),
                "headings": _normalize_string_list(source_snapshot.get("headings"), max_items=12, max_item_length=180),
                "service_blocks": _normalize_string_list(
                    source_snapshot.get("service_blocks"),
                    max_items=8,
                    max_item_length=180,
                ),
            },
            "operator_requirements": {
                "business_objectives": _normalize_string_list(
                    operator_requirements.get("business_objectives"),
                    max_items=12,
                    max_item_length=220,
                ),
                "requested_pages": _normalize_string_list(
                    operator_requirements.get("requested_pages"),
                    max_items=12,
                    max_item_length=220,
                ),
                "must_include": _normalize_string_list(
                    operator_requirements.get("must_include"),
                    max_items=12,
                    max_item_length=220,
                ),
                "must_avoid": _normalize_string_list(
                    operator_requirements.get("must_avoid"),
                    max_items=12,
                    max_item_length=220,
                ),
                "tone_preferences": _normalize_string_list(
                    operator_requirements.get("tone_preferences"),
                    max_items=12,
                    max_item_length=220,
                ),
                "calls_to_action": _normalize_string_list(
                    operator_requirements.get("calls_to_action"),
                    max_items=12,
                    max_item_length=220,
                ),
                "additional_notes": _normalize_string(operator_requirements.get("additional_notes"), max_length=1200),
            },
            "recommendations": {
                "top_titles": recommendation_titles,
                "categories": recommendation_categories,
            },
            "audit": {
                "overall_health_summary": _normalize_string(
                    audit_summary.get("overall_health_summary"),
                    max_length=500,
                ),
                "top_findings": audit_findings,
            },
            "competitors": {
                "overall_gap_summary": _normalize_string(
                    competitor_summary.get("overall_gap_summary"),
                    max_length=500,
                ),
                "top_gaps": competitor_highlights,
            },
            "selected_media_summary": {
                "selected_media_count": selected_media_count,
                "selected_usable_media_count": selected_usable_media_count,
                "categories": media_categories,
            },
            "enriched_supporting": {
                "replacement_summary": _normalize_string(enriched_notes.get("replacement_summary"), max_length=600),
                "homepage_value_proposition": _normalize_string(
                    enriched_notes.get("homepage_value_proposition"),
                    max_length=600,
                ),
                "about_business": _normalize_string(enriched_notes.get("about_business"), max_length=600),
                "service_highlights": _normalize_string_list(
                    enriched_notes.get("service_highlights"),
                    max_items=10,
                    max_item_length=220,
                ),
                "trust_signals": _normalize_string_list(
                    enriched_notes.get("trust_signals"),
                    max_items=10,
                    max_item_length=220,
                ),
                "faq_items": _normalize_string_list(
                    enriched_notes.get("faq_items"),
                    max_items=8,
                    max_item_length=220,
                ),
                "additional_notes": _normalize_string(enriched_notes.get("additional_notes"), max_length=800),
            },
            "business_site_context": {
                "display_name": _normalize_string(brand_business_facts.get("display_name"), max_length=160),
                "industry": _normalize_string(brand_business_facts.get("industry"), max_length=160),
                "primary_location": _normalize_string(brand_business_facts.get("primary_location"), max_length=160),
            },
        }
        return suggestion_context, context_sources_used[:8]

    def _request_requirement_field_suggestion(
        self,
        *,
        field: str,
        current_value: str | list[str] | None,
        suggestion_context: dict[str, object],
    ) -> object:
        provider_name = (_normalize_string(self.provider_name, max_length=64) or "").lower()
        if provider_name.startswith("mock"):
            return self._build_mock_requirement_field_suggestion(
                field=field,
                current_value=current_value,
                suggestion_context=suggestion_context,
            )
        if provider_name != "openai":
            raise SEOMigrationValidationError(
                "Requirement suggestion is not available for this provider.",
                failure_category="config_missing",
                failure_reason="unsupported_configuration",
                error_code=_REQUIREMENTS_SUGGESTION_REASON_NOT_AVAILABLE,
                retryable=False,
            )
        return self._request_openai_requirement_field_suggestion(
            field=field,
            current_value=current_value,
            suggestion_context=suggestion_context,
        )

    def _request_openai_requirement_field_suggestion(
        self,
        *,
        field: str,
        current_value: str | list[str] | None,
        suggestion_context: dict[str, object],
    ) -> object:
        api_key = _normalize_string(getattr(self.artifact_provider, "api_key", None), max_length=300)
        api_base_url = _normalize_string(getattr(self.artifact_provider, "api_base_url", None), max_length=300)
        model_name = _normalize_string(
            getattr(self.artifact_provider, "model_name", None), max_length=128
        ) or _normalize_string(
            self.provider_model_name,
            max_length=128,
        )
        timeout_seconds_raw = getattr(self.artifact_provider, "timeout_seconds", None)
        timeout_seconds = max(1, int(timeout_seconds_raw)) if isinstance(timeout_seconds_raw, int) else 30
        if api_key is None:
            raise SEOMigrationValidationError(
                "AI provider credentials are unavailable for requirement suggestion.",
                failure_category="config_missing",
                failure_reason="unsupported_configuration",
                error_code=_REQUIREMENTS_SUGGESTION_REASON_PROVIDER_UNAVAILABLE,
                retryable=False,
            )
        if api_base_url is None:
            api_base_url = "https://api.openai.com/v1"
        if model_name is None:
            model_name = "gpt-4o-mini"

        schema = {
            "type": "object",
            "additionalProperties": False,
            "properties": {
                "suggested_value": {
                    "type": ["array", "string", "null"],
                    "items": {"type": "string"},
                }
            },
            "required": ["suggested_value"],
        }
        user_payload = {
            "field": field,
            "current_value": current_value,
            "suggestion_context": suggestion_context,
        }
        payload = {
            "model": model_name,
            "input": [
                {
                    "role": "system",
                    "content": [
                        {
                            "type": "input_text",
                            "text": (
                                "You draft bounded requirement text for SMB website migration operators. "
                                "Use the provided context only. Keep output concise and practical. "
                                "Return only schema-valid JSON and never include secrets."
                            ),
                        }
                    ],
                },
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "input_text",
                            "text": (
                                "Suggest operator-owned requirement text for one field. "
                                "Do not reference hidden infrastructure details. "
                                "Return useful short list items the operator can edit.\n"
                                f"{json.dumps(user_payload, ensure_ascii=True, separators=(',', ':'))}"
                            ),
                        }
                    ],
                },
            ],
            "text": {
                "format": {
                    "type": "json_schema",
                    "name": "seo_migration_requirement_suggestion",
                    "schema": schema,
                    "strict": True,
                }
            },
        }
        body = json.dumps(payload, ensure_ascii=True).encode("utf-8")
        request = urllib.request.Request(
            url=api_base_url.rstrip("/") + "/responses",
            data=body,
            method="POST",
            headers={
                "Authorization": f"Bearer {api_key}",
                "Content-Type": "application/json",
            },
        )
        try:
            execution_response = execute_json_request(
                request=request,
                policy=AIExecutionPolicy(
                    feature_area="migration_requirements_suggestion",
                    timeout_seconds=timeout_seconds,
                    max_attempts=1,
                    max_input_size=120_000,
                ),
            )
        except AIExecutionError as exc:
            reason_code = _REQUIREMENTS_SUGGESTION_REASON_PROVIDER_UNAVAILABLE
            if exc.normalized_failure.reason == "request_too_large":
                reason_code = _REQUIREMENTS_SUGGESTION_REASON_BUDGET_REJECTED
            elif exc.normalized_failure.reason in {"response_malformed"}:
                reason_code = _REQUIREMENTS_SUGGESTION_REASON_PROVIDER_INVALID
            raise SEOMigrationValidationError(
                "Requirement suggestion provider request failed.",
                failure_category="provider_error",
                failure_reason="unknown",
                error_code=reason_code,
                retryable=bool(exc.normalized_failure.retryable),
            ) from exc
        try:
            response_json = json.loads(execution_response.body_text)
        except json.JSONDecodeError as exc:
            raise SEOMigrationValidationError(
                "Requirement suggestion response could not be parsed.",
                failure_category="provider_error",
                failure_reason="unknown",
                error_code=_REQUIREMENTS_SUGGESTION_REASON_PROVIDER_INVALID,
                retryable=True,
            ) from exc
        if not isinstance(response_json, dict):
            raise SEOMigrationValidationError(
                "Requirement suggestion response was invalid.",
                failure_category="provider_error",
                failure_reason="unknown",
                error_code=_REQUIREMENTS_SUGGESTION_REASON_PROVIDER_INVALID,
                retryable=True,
            )
        output_text = _extract_responses_output_text(response_json)
        if output_text is None:
            raise SEOMigrationValidationError(
                "Requirement suggestion output was empty.",
                failure_category="provider_error",
                failure_reason="unknown",
                error_code=_REQUIREMENTS_SUGGESTION_REASON_PROVIDER_INVALID,
                retryable=True,
            )
        try:
            suggestion_payload = json.loads(output_text)
        except json.JSONDecodeError as exc:
            raise SEOMigrationValidationError(
                "Requirement suggestion output could not be parsed.",
                failure_category="provider_error",
                failure_reason="unknown",
                error_code=_REQUIREMENTS_SUGGESTION_REASON_PROVIDER_INVALID,
                retryable=True,
            ) from exc
        if not isinstance(suggestion_payload, dict):
            raise SEOMigrationValidationError(
                "Requirement suggestion output was invalid.",
                failure_category="provider_error",
                failure_reason="unknown",
                error_code=_REQUIREMENTS_SUGGESTION_REASON_PROVIDER_INVALID,
                retryable=True,
            )
        return suggestion_payload.get("suggested_value")

    def _build_mock_requirement_field_suggestion(
        self,
        *,
        field: str,
        current_value: str | list[str] | None,
        suggestion_context: dict[str, object],
    ) -> list[str]:
        del current_value
        site_context = _normalize_json_dict(suggestion_context.get("site"))
        source_context = _normalize_json_dict(suggestion_context.get("source_snapshot"))
        recommendation_context = _normalize_json_dict(suggestion_context.get("recommendations"))
        media_context = _normalize_json_dict(suggestion_context.get("selected_media_summary"))
        industry = _normalize_string(site_context.get("industry"), max_length=120) or "local service"
        location = _normalize_string(site_context.get("primary_location"), max_length=120)
        top_heading = _normalize_string_list(source_context.get("headings"), max_items=1, max_item_length=120)
        top_recommendation = _normalize_string_list(
            recommendation_context.get("top_titles"),
            max_items=1,
            max_item_length=120,
        )
        media_category = _normalize_string_list(media_context.get("categories"), max_items=1, max_item_length=80)
        if field == "business_objectives":
            return [
                f"Clarify the {industry} value proposition for high-intent visitors.",
                (
                    f"Increase qualified quote requests from {location} visitors."
                    if location
                    else "Increase qualified quote requests from website visitors."
                ),
                (
                    f"Address priority SEO theme: {top_recommendation[0]}."
                    if top_recommendation
                    else "Strengthen trust and conversion messaging across key pages."
                ),
            ]
        if field == "requested_pages":
            return ["Homepage", "Services", "About", "Contact"]
        if field == "must_include":
            lines = [
                "Clear service areas and response expectations.",
                "Trust proof: licenses, certifications, and customer outcomes.",
            ]
            if top_heading:
                lines.append(f"Preserve useful source intent from heading: {top_heading[0]}.")
            return lines
        if field == "must_avoid":
            return [
                "Avoid unverifiable superlatives or compliance claims.",
                "Avoid keyword stuffing and duplicate paragraph blocks.",
            ]
        if field == "tone":
            return [
                "Clear, practical, and confidence-building.",
                "Professional and local-service oriented.",
            ]
        if field == "calls_to_action":
            lines = ["Request a Quote", "Schedule Service"]
            if media_category:
                lines.append(f"View {media_category[0].replace('_', ' ')} examples")
            return lines
        if field == "additional_notes":
            lines = [
                "Keep claims verifiable and tie trust signals to specific services.",
                "Preserve practical local-service language and clear response expectations.",
            ]
            if top_recommendation:
                lines.append(f"Prioritize recommendation evidence for: {top_recommendation[0]}.")
            return lines
        return []

    def _normalize_requirement_suggestion_value(self, *, field: str, value: object) -> list[str] | str | None:
        if field not in _REQUIREMENTS_SUGGESTION_SUPPORTED_FIELDS:
            return None
        if isinstance(value, list):
            normalized_list = _normalize_string_list(value, max_items=12, max_item_length=220)
            return normalized_list or None
        normalized_text = _normalize_string(value, max_length=5000)
        if normalized_text is None:
            return None
        split_items = _normalize_string_list(
            [part.strip() for part in normalized_text.split("\n") if part.strip()],
            max_items=12,
            max_item_length=220,
        )
        if split_items:
            return split_items
        return None

